// RecordError is the error unit record_error (E-2): an error of category store,
// which errors.As finds as each of them too.
type RecordError struct {
	*HyperStoreError
	pOffset *uint64
}

// Unwrap is the error of the category, which errors.As reads on.
func (e *RecordError) Unwrap() error { return e.HyperStoreError }

// Offset is the property record_error.offset (I-3).
func (e *RecordError) Offset() *uint64 { return e.pOffset }

func makeRecordError(base *HyperStoreError, r *Reader) *RecordError {
	e := &RecordError{HyperStoreError: base}
	if r.Tag() {
		var present0 uint64
		present0 = r.Uint()
		e.pOffset = &present0
	}
	return e
}

